import React from 'react';
import { useParams } from 'react-router-dom';

const JobDetails = () => {
    const { id } = useParams();
    // Fetch job details based on the id (this is a placeholder)
    const job = { title: 'Software Engineer', company: 'Tech Corp', description: 'Job description goes here.' };

    return (
        <div className="job-details">
            <h2>{job.title}</h2>
            <h3>{job.company}</h3>
            <p>{job.description}</p>
            <button>Apply Now</button>
        </div>
    );
};

export default JobDetails;
